package com.dailyplanner.di

import com.dailyplanner.BuildConfig
import com.dailyplanner.data.remote.LLMService
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object AIModule {

    @Provides
    @Singleton
    fun provideLLMService(): LLMService {
        val service = LLMService()
        // BuildConfig.GEMINI_API_KEY will be generated by Gradle
        // If it's empty (during first sync before user adds it), the service handles graceful failure.
        service.initialize(BuildConfig.GEMINI_API_KEY)
        return service
    }
}
